mapper.select:
SELECT COUNT(1)
FROM TBL_VOUCHER_POSTING_LOG
WHERE VOUCHER_ID = #{voucherId}

SELECT LOG_ID, VOUCHER_ID, VOUCHER_NO, OPERATION_TYPE, OPERATION_STATUS, ERROR_MESSAGE, REMARK, OPERATOR_ID, OPERATOR_NAME, OPERATION_TIME, BOOK_ID, TENANT_ID, CREATE_TIME FROM TBL_VOUCHER_POSTING_LOG WHERE 1=1
AND VOUCHER_ID = #{param.voucherId}
AND OPERATION_TYPE = #{param.operationType}
AND OPERATION_STATUS = #{param.operationStatus}
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
ORDER BY OPERATION_TIME DESC OFFSET #{param.offset} ROWS FETCH NEXT #{param.pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_VOUCHER_POSTING_LOG
WHERE 1=1

    AND VOUCHER_ID = #{param.voucherId}


    AND OPERATION_TYPE = #{param.operationType}


    AND OPERATION_STATUS = #{param.operationStatus}


    AND BOOK_ID = #{param.bookId}


    AND TENANT_ID = #{param.tenantId}
